(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["uz"] = {"ui":{"skip":"Mazmunga oʻtish","back":"← AI-gile’ga qaytish","lang.button":"Til: {name}","lang.dialog":"Tilni tanlang","lang.search":"Til qidirish","lang.none":"Mos til topilmadi","lang.notYet":"{name} hali tarjima qilinmagan","theme.aria":"Yorugʻ va qorongʻi mavzu oʻrtasida almashtirish","theme.toLight":"Yorugʻ mavzuga oʻtish","theme.toDark":"Qorongʻi mavzuga oʻtish","words.underline":"Sahifadagi bu soʻzlarning tagiga chizish","words.underlineHelp":"Maʼnosini koʻrish uchun nuqtali soʻz ustiga sichqonchani olib boring yoki unga bosing.","index.title":"AI-gile: sun’iy intellektli dasturchilar jamoangiz, bitta doskada","index.description":"AI-gile — sun’iy intellekt bilan kod yozadigan jamoalar uchun kanban doskasi. Siz uxlab yotganingizda ular ishlaydi; sizga esa qaror qilish, sinash va qabul qilish uchun bitta qisqa toʻplam qoladi.","hero.logoAlt":"AI-gile doskasi belgisi","hero.h1.html":"Sun’iy intellektli dasturchilar jamoangiz, bitta&nbsp;doskada.","hero.alpha":"🐣 Yopiq pre-alfa","hero.alphaTitle":"Hali erta va tugallanmagan: sinab koʻrganingiz uchun rahmat!","hero.lede":"Ular siz uxlayotganda ishlaydi. Ertalab sizni qisqa bir toʻplam kutadi: bir nechta savol, sinab koʻriladigan bir-ikki narsa, bitta-ikkita binafsha olmos. Bosing, qabul qiling, qahvangizga qayting.","dl.windows":"Windows ilovasi","dl.browser":"Brauzerda ishga tushirish","dl.soon":"Tez orada","dl.notify":"🔔 Ochilganda xabar bering","dl.notifySmall":"Alfa yoki beta","hero.secondary":"Agile, lekin jamoaga hech qachon stend-ap qahvasi kerak emas. (Baribir stend-ap oʻtkazishadi.)","pitch.h2":"AI-gile siz xohlagancha soʻzda","pitch.lede":"Uzunlikni tanlang: bir soʻzdan 144 gacha. Har bir uzunlik oʻz oʻlchamiga moslab yozilgan alohida tavsif. Sirpanchni suring yoki strelka tugmalaridan foydalaning.","pitch.rangeLabel":"Uzunlik soʻzlarda","pitch.dice":"🎲 boshqa variant","pitch.words.one":"{n} soʻz","pitch.words.other":"{n} soʻz","pitch.letters.one":"{n} harf","pitch.letters.other":"{n} harf","pitch.chars.one":"{n} belgi","pitch.chars.other":"{n} belgi","count.line.html.one":"Hozir doskada {n} karta bor","count.line.html.other":"Hozir doskada {n} karta bor","features.aria":"U nima qiladi","f.pile.h":"Siz uchun bitta toʻplam","f.pile.html":"<b>Siz uchun</b> barcha loyihalarda sizni kutayotgan hamma narsani yigʻadi: savollar, sinab koʻriladigan narsalar, faqat odam qila oladigan ishlar. Navbatingiz keyingisi nima ekanini va qancha vaqt olishini aytadi.","f.sleep.h":"Siz uxlaganingizda ishlaydigan jamoalar","f.sleep.p":"Har bir loyihaning rahbari va sun’iy intellekt agentlaridan iborat jamoasi bor. Kartaga izoh yozing, jamoa uygʻonadi, ishni bajaradi va charchagan odam ham kuzata oladigan qadamlar bilan qaytaradi.","f.tester.h":"Avval sun’iy intellekt tekshiruvchisi koʻradi","f.tester.p":"Sizga biror narsa yetib kelmasidan oldin tekshiruvchi ilovaning nusxasida qadamlarni bajaradi va nimani koʻrganini skrinshot bilan koʻrsatadi. Oʻtganlarini varaqlab chiqing va bir bosishda qabul qiling.","f.proof.h":"Va’da emas, dalil","f.proof.p":"Har bir topshirish nima oʻzgarganini koʻrsatadi: fayllarni, farqni, skrinshotlarni. Tayyor boʻldimi, deb har bir ilovani ochib chiqish shart emas.","f.chat.h":"Rahbarlaringiz bilan suhbatlashing","f.chat.p":"Discord uslubidagi yon panel: har bir loyiha uchun bitta belgi, sizga kerak joyda binafsha olmoslar. Rahbarga gʻoyani yozing; u uni kartalar va rejaga aylantiradi, yonida ✅ Boshlash tugmasi bilan.","f.tidy.h":"Oʻzi tartibni saqlaydi","f.tidy.p":"Bogʻliq kartalar bittaga birlashadi, chalkash sarlavhalar tuzatiladi, token tekshiruvi esa kodni yengil saqlaydi. Almashtiriladigan narsa kam, oʻylanadigan narsa kam.","f.private.h":"Sizniki, sizning kompyuteringizda","f.private.li1":"Doska oʻz kompyuteringizda ishlaydi va faqat sizga javob beradi.","f.private.li2":"Odamlar orasidagi shaxsiy xabarlar boshidan oxirigacha shifrlangan.","f.private.li3":"Akkauntlar yoʻq, kuzatuvchilar yoʻq, kukilar yoʻq.","f.lang.h":"Oʻz tilingizda","f.lang.p":"Golland, uels va yapon tillaridan tortib qaroqchi, Yoda va klingon tillarigacha 120 dan ortiq til, dasturchilar soʻzlari uchun inglizchaga tez qaytish tugmasi bilan.","tl.aria":"Birinchi suhbatdan yoʻl xaritasigacha boʻlgan vaqt chizigʻi","tl.h2":"Birinchi suhbatdan keyingi qadamgacha","tl.lede":"Haqiqiy sanalar va vaqtlar, oʻz vaqt mintaqangizda. Bugundan keyingisi — reja, sana va’da qilinmaydi.","tl.today":"Bugun","tl.planned":"rejalashtirilgan","tl.cards.one":"{n} karta","tl.cards.other":"{n} karta","join.h2":"Qoʻshiling","join.lede":"AI-gile’ni bitta kichkina odam va juda koʻp sabrli agentlar yaratmoqda. Hozircha u yopiq, doʻstlar bilan yopiq alfada. Ochilganda sinab koʻrmoqchimisiz?","join.btn":"Qiziqishimni qayd etish","join.small":"Sizga email yozamiz, boshqa hech narsa yoʻq","footer.tag":"AI-gile. Kuzatuvchilarsiz, kukilarsiz, stend-ap qahvasiz.","footer.licence":"Biznes litsenziyasi","footer.status":"Holat","footer.privacy":"Nimalarni saqlaymiz","form.sending":"Yuborilmoqda…","form.failed":"Boʻlmadi: keyinroq qayta urinib koʻring.","form.offline":"AI-gile bilan aloqa oʻrnatib boʻlmadi: keyinroq qayta urinib koʻring.","form.keep":"Bundan faqat sizga javob berish uchun foydalanamiz, keyin oʻchirib tashlaymiz. Kuzatuvchilar yoʻq, kukilar yoʻq.","form.keepLink":"Nimalarni saqlaymiz","interest.title":"AI-gile: alfa ochilganda xabar bering","interest.description":"AI-gile’ning yopiq alfasi yoki betasi ochilganda xabar topish uchun emailingizni qoldiring.","interest.h1":"🔔 Ochilganda xabar bering","interest.lede":"AI-gile yopiq pre-alfada. Emailingizni qoldiring, sizga joy topilganda bir marta yozamiz.","interest.email":"Emailingiz","interest.which":"Qaysi sinov?","interest.alpha":"Yopiq alfa: erta, dagʻal, koʻp oʻzgarishlar","interest.beta":"Beta: barqarorroq, keyinroq","interest.both":"Qaysi biri avval chiqsa, farqi yoʻq","interest.submit":"Meni roʻyxatga yozing","interest.thanks":"Rahmat! Siz roʻyxatdasiz.","licence.title":"AI-gile: biznes litsenziyasi","licence.description":"AI-gile’dan biznesingizda foydalanasizmi? Bepul biznes litsenziyasiga ariza bering.","licence.h1":"📜 Biznes litsenziyasi","licence.lede":"AI-gile’dan ishda foydalanasizmi? Kimligingiz va nima bilan shugʻullanishingizni yozing. Agar bu biroz yaxshilik qilsa, litsenziya bepul.","licence.company":"Kompaniya","licence.website":"Veb-sayt","licence.what":"Nima bilan shugʻullanasiz","licence.how":"Bu dunyoga qanday yordam beradi","licence.email":"Email","licence.submit":"Ariza berish","licence.thanks":"Rahmat! Email orqali javob beramiz.","status.title":"AI-gile holati","status.h1":"AI-gile holati","status.quiet":"Hammasi tinch","status.intro":"AI-gile hozir ishlayaptimi? Bu sahifa har 5 daqiqada veb-sayt, doska ulashish, qoʻngʻiroqlar va yuklab olishni tekshiradi.","status.up":"Ishlayapti ({ms} ms da javob berdi)","status.slow":"Oxirgi tekshiruvga javob bermadi, qayta urinilmoqda","status.down":"Ishlamayapti: oxirgi ikki tekshiruvga javob bermadi","status.svc.web":"Veb-sayt","status.svc.web.offers":"Shu sayt: AI-gile nima ekanligi va qiziqish formasi","status.svc.boards":"Doska ulashish","status.svc.boards.offers":"Ommaviy doskalar, doʻstlar orasidagi xabarlar va taklifnomalar","status.svc.calls":"Qoʻngʻiroqlar","status.svc.calls.offers":"AI-gile ichida ovozli va video qoʻngʻiroqlar, ekranni ulashish","status.svc.download":"Yuklab olish","status.svc.download.offers":"Windows oʻrnatuvchisi va taklif havolalari","status.checking":"Tekshirilmoqda…","status.offline":"Holat xizmatiga hozir ulanib boʻlmayapti (qayta urinilmoqda)","status.updated":"yangilandi: {ago}","status.justNow":"hozirgina","status.min":"{n} daqiqa oldin","status.hours":"{n} soat oldin","status.days":"{n} kun oldin","privacy.title":"AI-gile: nimalarni saqlaymiz","privacy.h1":"Nimalarni saqlaymiz","privacy.lede":"Qisqasi: faqat siz yuborgan narsa, u ham uzoq vaqtga emas.","privacy.only":"Faqat siz bizga yuborgan narsa: formaga yozganingiz, masalan emailingiz. Siz haqingizda boshqa hech narsa.","privacy.sealed":"U muhrlanadi, shuning uchun serverimiz uni oʻqiy olmaydi: brauzeringizda, joʻnab ketishidan oldin (eskiroq brauzerda esa yetib kelgan zahoti). Uni faqat oʻzimizning doskamiz ocha oladi.","privacy.server":"Doskamizga yetib borishi bilan serverdan oʻchiriladi. 30 kundan keyin ham u yerda qolgan har qanday narsa baribir oʻchiriladi.","privacy.board":"Uni doskamizda faqat sizga javob berguncha saqlaymiz, keyin u yerdan ham oʻchiramiz.","privacy.none":"Kuzatuvchilar yoʻq, kukilar yoʻq, analitika yoʻq.","privacy.local":"Tilingiz va yorugʻ yoki qorongʻi mavzu tanlovingiz oʻz brauzeringizda qoladi. Ular hech qachon bizga yuborilmaydi.","privacy.ask":"Tezroq oʻchirilishini xohlaysizmi? Xatimizga javob yozib, shuni ayting.","live.h2":"Uning qurilishini jonli kuzating","live.caption":"Har bir karta yashirilgan: siz ishning shaklini ko'rasiz, so'zlarni emas.","live.watching.one":"jonli: {n} kuzatmoqda","live.watching.other":"jonli: {n} kuzatmoqda","live.last.now":"Oxirgi karta hozirgina koʻchirildi","live.last.min.one":"Oxirgi karta {n} daqiqa oldin koʻchirildi","live.last.min.other":"Oxirgi karta {n} daqiqa oldin koʻchirildi","live.last.hour.one":"Oxirgi karta {n} soat oldin koʻchirildi","live.last.hour.other":"Oxirgi karta {n} soat oldin koʻchirildi","live.last.day.one":"Oxirgi karta {n} kun oldin koʻchirildi","live.last.day.other":"Oxirgi karta {n} kun oldin koʻchirildi","live.offline":"Jonli taxta biroz dam olyapti. Tez orada yana kiring.","live.cols":"Backlog|Bajarilishi kerak|Jarayonda|Jamoa tekshirmoqda|Siz test qilishingiz kerak|Jamoa uchun|Bajarildi"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotlar.","Topshirildi."]},{"n":2,"texts":["Robotlar kanbani.","Agentlar, tartibda.","Gʻoyalar, bajarildi."]},{"n":3,"texts":["Robotlar uchun kanban.","Gʻoyalar funksiyaga aylanadi.","Bepul agent kanbani."]},{"n":5,"texts":["Agentlar yuritadigan kanban doskasi.","Siz karta yozasiz. Agentlar quradi.","Bepul, mahalliy, sinalgan, biroz kulgili."]},{"n":8,"texts":["Sun’iy intellekt agentlari ishlaydigan bepul kanban doskasi.","Gʻoyani yozing. Agentlar quradi. Siz qabul qilasiz.","Bitta odam va koʻp sabrli robotlar uchun agile."]},{"n":13,"texts":["Kompyuteringizdagi kanban doskasi: kartalarni olib ishlaydiganlar esa sun’iy intellekt agentlari.","Gʻoya yozing. Agentlar jamoasi uni quradi. Tekshiruvchi esa sinab koʻradi.","Bepul, akkauntlarsiz, kuzatuvchilarsiz: bitta doska, bir nechta robot va hamma narsaga siz rahbar."]},{"n":21,"texts":["AI-gile — sun’iy intellekt dasturchi agentlari bilan ishlash uchun kanban doskasi. Kartalarni ular olib ishlaydi; siz esa ularni sinab koʻrasiz va qabul qilasiz.","Har bir loyihaning bitta rahbari va sun’iy intellekt agentlaridan iborat jamoasi bor. Istalgan kartaga izoh yozing, jamoa darhol ishga kirishadi.","Oʻz kompyuteringizda ishlaydigan bepul va shaxsiy vazifalar doskasi. Ishlaydiganlar — robotlar. Oxirida «ha» deydigan esa faqat siz, hamma vaqt."]},{"n":34,"texts":["Siz gʻoyalarni doskaga qoʻyasiz. Sun’iy intellekt agentlaridan iborat jamoa ularni ishlaydigan funksiyalarga aylantiradi, sinab koʻradi va sinab koʻrish uchun qadamlar bilan sizga qaytaradi. Siz aytmaguningizcha hech narsa tayyor hisoblanmaydi.","AI-gile — Rich hozir oʻzi boshqaradigan agentlarning katta yordami bilan uyda yasagan kanban doskasi. U bepul, sizning kompyuteringizda ishlaydi va sotilmaydi, balki shunchaki doʻstlar bilan ulashiladi, hech kimdan pul soʻralmaydi.","Oddiy kanban doskasini tasavvur qiling: ustunlar Backlogdan Bajarildigacha, faqat kartalarni sun’iy intellekt agentlari olib ishlaydi. Ular yutuqlar haqida xabar beradi, tiqilib qolsa soʻraydi va doimo sizning roziligingizni kutadi."]},{"n":55,"texts":["AI-gile — jamoasi sun’iy intellekt agentlaridan iborat kanban doskasi. Har bir loyihada ishni rejalashtiradigan rahbar va uni bajaradigan yordamchilar bor. Funksiya tayyor boʻlganda sun’iy intellekt tekshiruvchisi uni sinab koʻradi va skrinshot oladi, keyin u sizning toʻplamingizga tushadi. Qabul qiling yoki izoh yozing, ular qayta ishlaydi.","Bu bir kishi bir vaqtda koʻplab sun’iy intellekt kod yozish seanslarini kuzatib borish yoʻli sifatida boshlandi va chinakam doskaga aylandi. U sizning kompyuteringizda ishlaydi, akkaunt talab qilmaydi va kuzatuvchilari yoʻq. Doʻstlar va qiziquvchilar uchun bepul. U hali tugallanmagan ham, shuning uchun dagʻalliklar va goho kutilmagan holatlarni kuting.","Mana, halol variant. Gʻoyalarni baribir siz oʻylab topasiz, natijalarni ham baribir siz tekshirasiz. AI-gile esa oraliqdagi hamma narsani qiladi: kartalarni tartibda saqlaydi, siz izoh yozganingizda kerakli agentni uygʻotadi, aynan nima oʻzgarganini koʻrsatadi va hammasini faqat siz uchun bitta qisqa toʻplamga yigʻadi. Boshqa hech narsa shart emas."]},{"n":89,"texts":["AI-gile — oʻz kompyuteringizda ishga tushiradigan bepul kanban doskasi. Har bir loyihada odamlar oʻrniga sun’iy intellekt agentlaridan iborat jamoa bor: gʻoyalaringizni kartalar va rejaga aylantiradigan rahbar hamda kartalarni ustuvorlik tartibida oladigan yordamchilar. Biror narsa qurib boʻlinganda sun’iy intellekt tekshiruvchisi sinov qadamlarini bajaradi va nimani koʻrganini sizga koʻrsatadi. Keyin u «Siz uchun» deb nomlangan bitta toʻplamda kutadi. Siz qabul qilasiz yoki izoh yozasiz, jamoa esa yana urinib koʻradi. Siz boʻlmasangiz, hech narsa «Bajarildi»ga yetmaydi.","Kutilmagan ba’zi imkoniyatlar ham bor. Tungi qorovul siz uxlaganingizda «Bajarilishi kerak» ustunini toʻldirib turadi va sizdan javob talab qilmaydigan kartalarni tanlaydi. Token hisoblagichi agentlar bugun va shu hafta qancha sarflaganini koʻrsatadi, «Tokensiz rejim» esa ularga sarflashni toʻxtatishni buyuradi. Doʻstlaringizga xabar yozishingiz mumkin, shaxsiy xabarlar esa boshidan oxirigacha shifrlangan. Doska taxminan 120 tilda gapiradi, jumladan golland, flamand, qaroqchi va klingon tillarida. Bularning hech biri bir tiyin turmaydi, hech kim sizga biror narsa sotmoqchi ham emas.","AI-gile — kichik, shaxsiy loyiha, kompaniya emas. Rich bir nechta sun’iy intellektli kod loyihasini har bir ilovani alohida ochmasdan kuzatib borishni xohladi, shuning uchun agentlar bilan birga buning uchun doska yasadi, keyin esa qolgan qismini ham oʻsha doska bilan qurdi. U hozir yopiq pre-alfada, ya’ni bir hovuch doʻstlar uchun asosan ishlaydi. Narxlar sahifasi yoʻq, axborot byulleteni yoʻq, oʻsish rejasi ham yoʻq. Agar bularning hammasi foydali tuyulsa, u bir oz kengroq ochilganda sinab koʻrishni soʻrashingiz mumkin."]},{"n":144,"texts":["AI-gile — bitta odam va koʻplab sun’iy intellekt agentlari uchun kanban doskasi. U oʻz kompyuteringizda ishlaydi va butunlay bepul. Siz loyihalar qoʻshasiz, har bir loyiha esa oʻz rahbari va kichik jamoasini oladi. Rahbar bilan Discord’dagiga oʻxshab suhbatlashasiz va gʻoyani tasvirlab berasiz; rahbar uni kartalar va rejaga aylantiradi, keyin «Boshlash» tugmasini bosishingizni kutadi. Jamoa kartalarni ustuvorlik tartibida birma-bir ishlab chiqadi, buning uchun til modellari uchun yasalgan oddiy buyruq qatoridan foydalanadi. Biror narsa sizga qaytishidan oldin sun’iy intellekt tekshiruvchisi ilovaning nusxasida barcha qadamlarni bajaradi va skrinshot biriktiradi. Tayyor ish oʻzgargan fayllar va farq bilan sizning toʻplamingizga tushadi. Siz uni qabul qilasiz yoki izoh qoldirasiz, jamoa esa uygʻonib, qayta urinib koʻradi. Kartani «Bajarildi» ustuniga faqat siz va faqat oʻzingiz koʻchira olasiz.","AI-gile bilan taxminan bir kun shunday oʻtadi. Kechqurun bir nechta izoh qoldirasiz: bu tugma notoʻgʻri joyda turibdi, u roʻyxatni saralash kerak, qorongʻi mavzu boʻlsa-chi. Siz uxlashga ketasiz. Agentlar izohlarni oʻqiydi, oʻzgartirishlarni qiladi, hammasini sinab koʻradi va sizga qaytaradi. «Bajarilishi kerak» boʻshab qolsa, tungi qorovul uni backlogdan sizdan javob talab qilmaydigan kartalar bilan toʻldiradi. Ertalab bitta qisqa toʻplam kutadi: bir nechta savol va sinab koʻriladigan bir nechta narsa, har biri uyqusirab turgan odam ham bajara oladigan qadamlar va ishlayotganini koʻrsatadigan skrinshot bilan. Siz birma-bir bosib chiqasiz, yaxshilarini qabul qilasiz, qolganlarini qaytarasiz. Token hisoblagichi bularning hammasi qancha sarflaganini koʻrsatadi, «Tokensiz rejim» esa tejamkor haftalar uchun tayyor turadi. Keyin nonushta qilasiz, bunda agentlar hozircha afsuski yordam bera olmaydi.","Avval AI-gile nima emasligi haqida. U startap emas, sotuvga qoʻyilmagan va hech kim maʼlumotlaringizni yigʻmaydi. U kompyuteringizda ishlaydigan, akkauntsiz, kuzatuvchisiz va kukisiz bepul doska. U nima esa: barcha sun’iy intellektli kod loyihalarini bir vaqtda koʻrish uchun yagona saranjom joy, bunda kartalarni agentlar jamoasi bajaradi, qarorlarni esa siz qabul qilasiz. U bogʻliq kartalarni birlashtiradi, chalkash sarlavhalarni tuzatadi va kod qanchalik yengil qolayotganini kuzatib turadi. U taxminan 120 tilda gapiradi, golland va flamand tillaridan tortib qaroqchi va klingon tillarigacha. Doʻstlar bir-biriga shaxsiy va shifrlangan xabar yozishi mumkin. Uni Rich va juda koʻp sabrli agentlar yaratdi, asosan oʻzidan oʻzi foydalanib. U hozir yopiq pre-alfada, shuning uchun ba’zi joylari dagʻal. Qiziq tuyulsa, yaxshilab soʻrang, balki boshqalardan erta kirib qolarsiz."]}],"quips":{"1":"Bitta soʻz. Jasur. Balki juda jasur.","3":"Uchta soʻz. Allaqachon koʻp mahsulot sahifalaridan halolroq.","8":"Sakkizta soʻz. Baribir bitta stend-apdan qisqa.","21":"Aytgancha, uzunliklar story point’lar. Albatta-da.","55":"Ellik beshta soʻz. Siz oʻqiguncha ikkita karta tugadi.","144":"Bu eng uzuni. 233 yoʻq. Agentlar uxlashga ketdi."}},"timeline":{"first-idea.name":"Birinchi gʻoya","first-idea.line":"Hali bitta qator kod boʻlmagan paytdagi eng birinchi suhbat.","first-board.name":"Birinchi doska","first-board.line":"Oʻz yaratilishini kuzatib boradigan doska: kartalar, ustunlar, sudrab tashlash, loyihalar.","team-roles.name":"Jamoa va rollar","team-roles.line":"Agent profillari, jamoa shablonlari, maydonlar va kim nima qilishi.","install.name":"Oʻrnatish va relizlar","install.line":"Doʻst oʻrnata oladigan zip, oʻz-oʻzidan yangilanish, kanallar va ortga qaytarish.","usage-saver.name":"Sarfni tejash","usage-saver.line":"Ishga tushirishlar narxini oʻlchash, kodni yengil saqlash, limitingizni asrash.","friends.name":"Doʻstlar va ulashish","friends.line":"Shaxsiy xabarlar, aralashtirilgan uzatgich, takliflar, rollar va umumiy loyihalar.","languages.name":"Tillar","languages.line":"Ekrandagi har bir matn til faylida, avval golland va flamand tillari.","ai-tester.name":"Sun’iy intellekt tekshiruvchisi","ai-tester.line":"Tekshiruvchi har bir topshirishni avval koʻrib chiqadi va nimani koʻrganini koʻrsatadi.","website.name":"Veb-sayt","website.line":"aigile.lol, tizer va shu vaqt chizigʻi.","streaming.name":"Chat va strimlar","streaming.line":"Discord, Twitch, OBS, strimer rejimi, GIFlar va emojilar.","no-ai.name":"Sun’iy intellektsiz nashr","no-ai.line":"Sun’iy intellektsiz kod yozadiganlar uchun doska va ochiq doskalar.","night-watch.name":"Tungi qorovul","night-watch.line":"Qorovul va Scrum Master siz uxlaganingizda jamoalarni ish ustida ushlab turadi.","p-more.name":"Qolgan hamma narsa","p-more.line":"Navbatini kutayotgan kichikroq gʻoyalar.","p-android.name":"Telefon va Android","p-android.line":"Doskangizga telefondan kirish, keyin esa mahalliy Android ilovasi.","p-release.name":"Alfa va undan keyin","p-release.line":"Yopiq alfa, jonli sayt, keyin beta.","p-languages.name":"Koʻproq tillar","p-languages.line":"Yuzdan ortiq til va til oʻrganuvchilar uchun immersiya rejimi.","p-engines.name":"Koʻproq sun’iy intellekt dvigatellari","p-engines.line":"Har bir agent uchun Claude, Codex yoki Gemini’ni tanlang.","p-pro.name":"Professional amaliyot","p-pro.line":"Xavf belgilari, birlashtirish eshiklari, hodisa kartalari va toʻsiqlar.","p-self.name":"Sizga gʻamxoʻrlik","p-self.line":"Charchoq rejimi, oʻzingizga qarash eslatmalari va 4:20.","p-servers.name":"Serverlar va kengayish","p-servers.line":"Umumiy server sozlamalari, rollar va oʻsishni rejalashtirish.","p-livestream.name":"Strim qoʻshimchalari","p-livestream.line":"Twitch chati, shaxsiy emojilar va ochiq jonli koʻrinish."},"words":{"button":"📖 Dasturchi soʻzlari","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Soʻz qidirish…","none":"Bunday soʻz yoʻq.","close":"Yopish","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Loyihaning kod papkasi va commitlarning toʻliq tarixi, odatda GitHubda ham saqlanadi.","also":["repozitoriy"]},{"id":"branch","g":"build","word":"Branch","text":"Kodda alohida ish chizigʻi, shunda asosiy versiyaga tegmasdan oʻzgartirishlar kiritish mumkin.","also":["branchlar"]},{"id":"commit","g":"build","word":"Commit","text":"Kodning nima oʻzgargani haqida qisqa izoh bilan saqlangan nusxasi. Unga doim qaytish mumkin.","also":["commitlar"]},{"id":"push","g":"build","word":"Push","text":"Saqlangan nusxalarni (commitlarni) shu kompyuterdan GitHubga yuborish, shunda ular zaxiralanadi va ulashiladi."},{"id":"merge","g":"build","word":"Merge","text":"Branchdagi oʻzgarishlarni asosiy versiyaga qayta qoʻshish."},{"id":"pr","g":"build","word":"Pull request","text":"Branchdagi oʻzgarishlarni tekshirib, asosiy versiyaga qoʻshishni soʻrash.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kodning vazifasini oʻzgartirmasdan tartibga solish: kichikroq fayllar, aniqroq nomlar, kamroq takrorlash."},{"id":"bug","g":"build","word":"Bug","text":"Ishlashi kerak boʻlganidek ishlamayotgan narsa.","also":["buglar"]},{"id":"test","g":"build","word":"Test","text":"Tugagan ishni qabul qilishdan oldin, soʻralganini bajarayotganini tekshirish uchun sinab koʻrish.","also":["testlar"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Yangi versiyani ishga tushirish, masalan odamlar foydalanadigan serverga qoʻyish."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Hali rejalashtirilmagan gʻoyalar va ishlar. «Bajarilishi kerak»ga oʻtmaguncha, ular ustida ish olib borilmaydi."},{"id":"sprint","g":"team","word":"Sprint","text":"Kelishilgan kartalar toʻplamini tugatish uchun qisqa ish davri (koʻpincha bir-ikki hafta).","also":["sprintlar"]},{"id":"standup","g":"team","word":"Stand-up","text":"Qisqa yigʻilish: jamoaning har bir aʼzosi nima qildi, keyin nima qiladi va nima toʻsqinlik qilmoqda.","also":["standup","stand-uplar"]},{"id":"kanban","g":"team","word":"Kanban","text":"Ustunlari (Bajarilishi kerak, Jarayonda, Bajarildi) boʻlgan doska; ish davomida kartalar chapdan oʻngga oʻtadi."},{"id":"wip","g":"team","word":"WIP limit","text":"Jarayondagi ish: ustunda eng koʻpi bilan nechta karta boʻlishi kerak, shunda jamoa yangisini boshlashdan oldin boshlaganini tugatadi.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Vazifa ustida mustaqil ishlaydigan AI: kodni oʻqiydi, oʻzgartirishlar kiritadi, tekshiruvlarni ishga tushiradi va hisobot beradi.","also":["agentlar"]},{"id":"token","g":"team","word":"Token","text":"AI sarfi hisoblanadigan birlik: taxminan oʻqilgan yoki yozilgan matnning bir necha harfi. Token kam boʻlsa, tarifingizdan koʻproq qoladi.","also":["tokenlar"]},{"id":"hook","g":"team","word":"Hook","text":"Belgilangan paytda oʻzi ishlaydigan kichik buyruq, masalan AI sessiyasi boshlanganda, shunda jamoa izohlaringizni eshitadi.","also":["hooklar"]}]}};
